def t(k):
    while k % 2 == 0:
        k //= 2
    return k

# For each a, check if there exists n such that all differences t(n+a+i)-t(n+i) for i=0..a-1 are divisible by 4
def check_a(a, max_n=10000):
    for n in range(1, max_n+1):
        ok = True
        for i in range(a):
            if (t(n+a+i) - t(n+i)) % 4 != 0:
                ok = False
                break
        if ok:
            return n
    return None

for a in range(1, 40):
    result = check_a(a, max_n=100000)
    if result is not None:
        print(f"a={a}: works, n={result}")
    else:
        print(f"a={a}: no solution found up to n=100000")
